              <div class="chart-left">
                <span class="chart-name">{{ chart.name }}</span>
                <span class="chart-level">Lv.{{ Number(chart.level).toFixed(1) }}</span>
              </div>

              <div class="chart-right">
                <span class="chart-score dt-num">{{ chart.score }}</span>
                <span class="chart-value dt-num">{{ Number(chart.value).toFixed(4) }}</span>
              </div>
            </div>
          </template>
        </div>
      </div>
