</template>

<script setup>
import { computed } from 'vue'

const props = defineProps({
  songList: { type: Object, required: true },
  mainColor: { type: String, required: true },
  textColor: { type: String, required: true }
})

const sortedList = computed(() => {
  return Object.values(props.songList).sort((a, b) => a.player.rank - b.player.rank)
})

const goToLink = (player) => {
  if (player.bvid) window.open(`https://www.bilibili.com/video/${player.bvid}`, '_blank')
}
