<template>
  <div class="song-wrapper">
    <div class="card-grid">
      <div
        class="stage-section"
        v-for="(stageData, stageName, stageIndex) in safeSongList"
        :key="stageName"
        :id="stageAnchorId(stageIndex)"
      >
        <div class="dt-section__head">
          <h2 class="dt-section__title">{{ stageName }}</h2>
        </div>

        <div
          class="song-card"
          v-for="(groupData, groupName, groupIndex) in stageData"
          :key="`${stageName}-${groupName}`"
          :id="groupAnchorId(stageIndex, groupIndex)"
        >
          <div class="group-item">
            <div class="group-sub-title">
              {{ stageName }}
            </div>
            <div class="group-title">
              {{ groupName }}
            </div>
            <div class="divider"></div>

            <div class="player-list">
              <div
                class="player-item"
                :class="{ 'player-item--link': !!playerLink(player) }"
                v-for="player in getPlayerList(groupData)"
                :key="player.uid"
                :title="playerLink(player) ? `打开 ${player.name} 的 B 站主页` : ''"
                @click="openPlayer(player)"
              >
                <div class="player-left">
                  <div class="player-name">
                    {{ player.name }}
                  </div>
                  <div class="player-uid">
                    @{{ player.id }}
                  </div>
                </div>

                <div class="player-right">
                  <div class="total-score dt-num">
                    {{ player.total_score }}
                  </div>
                  <span
                    class="status-tag"
                    :class="{ pass: player.result === 'T', fail: player.result === 'F' }"
                  >
                    {{ player.status }}
                  </span>
                </div>
              </div>
            </div>
            <div class="divider"></div>

            <div class="table-wrapper">
              <table class="score-table">
                <thead>
                  <tr>
                    <th>谱面</th>
                    <th
                      v-for="player in getPlayerList(groupData)"
                      :key="player.uid"
                    >
                      {{ player.name }}
                    </th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-for="(song, idx) in getChartsList(groupData)" :key="idx">
                    <td>
                      {{ song }}
                    </td>
                    <td
                      v-for="player in getPlayerList(groupData)"
                      :key="player.uid"
                    >
                      {{ player.scores?.[idx] ?? 0 }}
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { computed } from 'vue'
import { stageAnchorId, groupAnchorId } from '../../composables/pmtAnchors.js'

const props = defineProps({
  songList: { type: Object, required: true },
  mainColor: { type: String, required: true },
  textColor: { type: String, required: true }
})

/** 选手主页地址：赛况数据里每位选手都带 B 站 uid，没有 uid 就没法跳（返回空串，整行不可点） */
const playerLink = (player) => {
  const uid = player?.uid
  return uid ? `https://space.bilibili.com/${uid}` : ''
}

const openPlayer = (player) => {
  const link = playerLink(player)
  if (!link) return
  window.open(link, '_blank', 'noopener')
}

const safeSongList = computed(() => {
  return props.songList && typeof props.songList === 'object' ? props.songList : {}
})

const getPlayerList = (groupData) => {
  if (!groupData?.players || typeof groupData.players !== 'object') return []
  return Object.values(groupData.players)
    .map(item => ({
      ...item?.player,
      scores: item?.scores || [],
      total_score: item?.total_score ?? 0,
      result: item?.result ?? '',
      status: item?.status ?? '未知'
    }))
    .sort((a, b) => {
      const sa = Number(a.total_score) || 0
      const sb = Number(b.total_score) || 0
      return sb - sa
    })
}

const getChartsList = (groupData) => {
  return groupData?.charts || []
}
</script>

