<script setup>
import { loadJson } from '../../api/jsonCache.js'
import pmtPCard from '../../components/cards/pmtPCard.vue'
import pmtRCard from '../../components/cards/pmtRCard.vue'
import pmtSCard from '../../components/cards/pmtSCard.vue'
import { ref, onMounted, computed, onUnmounted, watch } from 'vue'
import { useRemScale } from '../../utils/rem.js'
import { setAnchorNav, clearAnchorNav } from '../../composables/useAnchorNav.js'
import { buildMatchSections, buildRankSections, rankAnchorId } from '../../composables/pmtAnchors.js'

useRemScale()

// 每年比赛的主题色，只用在选中年份/选中的赛段标签上
const yearConfig = {
  2024: {
    color: '#3E3146',
    text: '#F7ED01',
    file: '/files/pmt/sea2024.json',
    dataFile: '/files/pmt/data2024.json',
    matchFile: '/files/pmt/match2024.json'
  },
  2025: {
    color: '#323232',
    text: '#FF8E34',
    file: '/files/pmt/sea2025.json',
    dataFile: '/files/pmt/data2025.json',
    matchFile: '/files/pmt/match2025.json'
  },
  2026: {
    color: '#322A61',
    text: '#FFFFFF',
    file: '/files/pmt/sea2026.json',
    dataFile: '/files/pmt/data2026.json',
    matchFile: '/files/pmt/match2026.json'
  }
}

const selectedYear = ref('2026')
const activeTab = ref('预选')
const songList = ref({})
const matchList = ref({})
const rankList = ref([])

const yearColor = computed(() => yearConfig[selectedYear.value].color)
const yearTextColor = computed(() => yearConfig[selectedYear.value].text)

const tabStyle = (year) => {
  return selectedYear.value === year
    ? { background: yearConfig[year].color, color: yearConfig[year].text }
    : {}
}

// 赛段标签沿用年份主题色，未选中时不染色
const sectionStyle = (tab) => {
  return activeTab.value === tab
    ? { background: yearConfig[selectedYear.value].color, color: yearConfig[selectedYear.value].text }
    : {}
}

const fetchSongData = async () => {
  const filePath = yearConfig[selectedYear.value].file
  const fileRankPath = yearConfig[selectedYear.value].dataFile
  const fileMatchPath = yearConfig[selectedYear.value].matchFile
  const data = await loadJson(filePath)
  const rank = await loadJson(fileRankPath)
  const match = await loadJson(fileMatchPath)
  songList.value = data
  matchList.value = match
  rankList.value = rank
}

const changeYear = (year) => {
  selectedYear.value = year
  fetchSongData()
}

// 排名原数据里前三名分成「冠军 / 亚军 / 季军」三节，页面合成一节「3强」，不再区分名次
const TOP3_TITLES = ['冠军', '亚军', '季军']

// 排名标签下的分节：3强排在最前，其余名次（8强 / 16强…）按数据里的顺序铺开
const rankSections = computed(() => {
  const rankData = rankList.value && typeof rankList.value === 'object' ? rankList.value : {}
  const sections = []
  const top3List = []
  for (const title of Object.keys(rankData)) {
    const list = Array.isArray(rankData[title]) ? rankData[title] : []
    if (TOP3_TITLES.includes(title)) {
      top3List.push(...list)
      continue
    }
    sections.push({ key: title, title: `PMT${selectedYear.value}-${title}`, list, top3: false })
  }
  if (top3List.length) {
    sections.unshift({
      key: '3强',
      title: `PMT${selectedYear.value}-3强`,
      list: top3List,
      top3: true
    })
  }
  return sections
})

onMounted(() => {
  fetchSongData()
})

// 本页目录：只登记当前标签下的分区——赛况是「赛段 → 分组」两级，
// 排名是 3强 / 8强… 各一节；预选是一张张平铺的选手卡，没有可跳的分区，目录不显示
const anchorSections = computed(() => {
  if (activeTab.value === '赛况') return buildMatchSections(matchList.value)
  if (activeTab.value === '排名') return buildRankSections(rankSections.value)
  return []
})

watch(
  anchorSections,
  (sections) => {
    if (sections.length) setAnchorNav(sections)
    else clearAnchorNav()
  },
  { immediate: true }
)

onUnmounted(clearAnchorNav)

</script>

<template>
  <div class="dt-page">

    <div class="dt-row control-wrapper">
      <div class="dt-tabs">
        <button
          v-for="year in ['2025', '2026']"
          :key="year"
          class="dt-tab"
          :class="{ 'dt-tab--active': selectedYear === year, 'is-year-active': selectedYear === year }"
          :style="tabStyle(year)"
          @click="changeYear(year)"
        >
          {{ year }}
        </button>
      </div>

      <div class="dt-tabs">
        <button
          v-for="tab in ['预选', '排名', '赛况']"
          :key="tab"
          class="dt-tab"
          :class="{ 'dt-tab--active': activeTab === tab, 'is-section-active': activeTab === tab }"
          :style="sectionStyle(tab)"
          @click="activeTab = tab"
        >
          {{ tab }}
        </button>
      </div>
    </div>

    <section v-if="activeTab === '排名'" class="rank-wrapper">
      <div
        v-for="(section, index) in rankSections"
        :key="section.key"
        :id="rankAnchorId(index)"
        class="rank-section"
      >
        <div class="dt-section__head rank-head">
          <h2 class="dt-section__title">{{ section.title }}</h2>
        </div>

        <pmt-r-card
          :song-data="section.list"
          :top3="section.top3"
          :main-color="yearColor"
          :text-color="yearTextColor"
        />
      </div>
    </section>

    <section v-else-if="activeTab === '预选'">
      <pmt-p-card
        :song-list="songList"
        :main-color="yearColor"
        :text-color="yearTextColor"
      />
    </section>

    <section v-else-if="activeTab === '赛况'">
      <pmt-s-card
        :song-list="matchList"
        :main-color="yearColor"
        :text-color="yearTextColor"
      />
    </section>
  </div>
</template>

<style scoped>
.control-wrapper {
  justify-content: space-between;
  margin-bottom: var(--dt-space-5);
}

.is-year-active,
.is-section-active {
  font-weight: 600;
}

.rank-wrapper {
  width: 100%;
}

.rank-head {
  margin-bottom: var(--dt-space-3);
}

.rank-head + * {
  margin-bottom: var(--dt-space-6);
}

@media (max-width: 900px) {
  .control-wrapper {
    justify-content: flex-start;
  }
}
</style>
